% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:504-505) quantifies
% the pairwise-agreement hypothesis over every pair (x, y_1), including pairs carrying
% probability zero under D, on which no conditional distribution of y_2 is defined; the
% hypothesis is restated here over the pairs of positive marginal probability, the only
% pairs the sampling in the hypothesis can refer to and the only ones the averaged
% conclusion depends on. The NEEXP original (references/neexp-paper/
% 05_quantum_preliminaries.tex:1000-1008, label fact:low-degree-sandwich-on-steroids)
% conditions on a fixed question tuple with the same restriction left implicit.
% The source states the lemma for symmetric strategies
% (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:84-86,174-176) and its imported
% proof (references/neexp-paper/05_quantum_preliminaries.tex:1150-1175) exchanges the
% tensor factors of the second codeword measurement. The hypothesis eq:pasting-1-sym
% below is the only consequence of that convention the proof uses; the statement
% without it is unattested (docs/paper-gaps/qpbt_pasting-product-error.tex, issue #201).
\begin{lemma}[Pasting two consistent measurements; Fact 4.35 in \cite{Natarajan2018NEEXP}]\label{lem:pasting}
	\lean{MIPStarRE.QPBT.pastedMeasurement}
	\lean{MIPStarRE.QPBT.exists_pasting_error}
	\leanok
	\uses{def:consistency, def:bracket, def:povm-conventions}
	Let $\mathcal D$ be a distribution on $(x, y_1, y_2) \in \mathcal X \times \mathcal Y_1 \times \mathcal Y_2$. For $i \in \{1,2\}$ let $\mathcal G_i$ be a collection of functions $g_i \colon \mathcal Y_i \to \mathcal R_i$ and let $\{(G_i)^x_g\}_{g \in \mathcal G_i}$ be families of measurements such that $\{(G_2)^x_g\}_g$ is projective for every $x$. Suppose further that for every pair $(x, y_1)$ of positive probability under the marginal of $\mathcal D$ on $\mathcal X \times \mathcal Y_1$ (the only pairs for which the conditional distribution of $y_2$ under $\mathcal D$ is defined; pairs of marginal probability zero are subject to no requirement) it holds that for $g_2 \ne g_2' \in \mathcal G_2$ the probability, on average over $y_2$ chosen from $\mathcal D$ conditioned on $(x, y_1)$, that $g_2(y_2) = g_2'(y_2)$ is at most $\eta$. Let $\{A^{x,y_1,y_2}_{a_1,\,a_2}\}$ be a family of projective measurements with outcomes $(a_1, a_2) \in \mathcal R_1 \times \mathcal R_2$ such that for $i \in \{1,2\}$,
	\begin{equation}\label{eq:pasting-1}
		A^{x,y_1,y_2}_{a_i} \ot \Id \simeq_\delta \Id \ot (G_i)^x_{[\operatorname{eval}_{y_i}(\cdot)=a_i]}
	\end{equation}
	and
	\begin{equation}\label{eq:pasting-2}
		A^{x,y_1,y_2}_{a_1,\,a_2} \ot \Id \simeq_\delta \Id \ot A^{x,y_1,y_2}_{a_1,\,a_2}\,,
	\end{equation}
	where $A^{x,y_1,y_2}_{a_i}$ denotes the marginal on the $i$-th part of the outcome (Definition~\ref{def:povm-conventions}). Suppose finally that the second comparison in \eqref{eq:pasting-1} also holds with the two tensor factors exchanged,
	\begin{equation}\label{eq:pasting-1-sym}
		(G_2)^x_{[\operatorname{eval}_{y_2}(\cdot)=a_2]} \ot \Id \simeq_\delta \Id \ot A^{x,y_1,y_2}_{a_2}\,,
	\end{equation}
	the first symmetric equivalent of that comparison in the sense of Definition~\ref{def:symmetric-equivalents}. That definition is stated later, in Chapter~\ref{chap:qpbt-observables}, for the six registers of the expanded state; it is referred to here in its plain bipartite form, namely the same comparison with the two tensor factors exchanged. The source states the lemma for symmetric strategies, for which \eqref{eq:pasting-1-sym} is the second comparison in \eqref{eq:pasting-1} read from the other player; it is the only consequence of that convention used by the imported proof, and the statement without it is unattested (\cite{gap:qpbt_pasting-product-error}). Define a family of measurements $\{J^x_{g_1,\,g_2}\}$ by
	\begin{equation}\label{eq:pasting-2a}
		J^x_{g_1,\,g_2} = (G_2)^x_{g_2}\, (G_1)^x_{g_1}\, (G_2)^x_{g_2}\,.
	\end{equation}
	Then there is a
	\begin{equation}\label{eq:def-deltap}
		\delta_{\mathrm{pasting}} = \delta_{\mathrm{pasting}}(\eta, \delta) = \poly(\eta, \delta)
	\end{equation}
	such that
	\begin{equation}\label{eq:pasting-3}
		A^{x,y_1,y_2}_{a_1,\,a_2} \ot \Id \simeq_{\delta_{\mathrm{pasting}}} \Id \ot J^x_{[\operatorname{eval}_{y_1}(\cdot)=a_1,\, \operatorname{eval}_{y_2}(\cdot)=a_2]}\,.
	\end{equation}
	Neither the exponent nor the constant in $\poly(\eta, \delta)$ is made explicit in the source; both are universal constants inherited from the proof of Fact 4.35 in \cite{Natarajan2018NEEXP}. The literal product-form convention for this notation is incompatible with the unrestricted error domain in the lemma; a two-dimensional counterexample and the required correction are recorded in \cite{gap:qpbt_pasting-product-error}.
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:pasting-measurement, lem:pasting-coarse-commutator,
		lem:pasting-explicit-error}
	Stated in the source without proof, as an import of Fact 4.35 of \cite{Natarajan2018NEEXP}; the argument below is recorded with explicit constants in \cite{gap:qpbt_pasting-product-error}. Write $P_{a_1} = (G_1)^x_{[\operatorname{eval}_{y_1}(\cdot)=a_1]}$, $Q_{a_2} = (G_2)^x_{[\operatorname{eval}_{y_2}(\cdot)=a_2]}$ and $G_{g_2} = (G_2)^x_{g_2}$. Since the answer projections act on the first factor and commute with every operator on the second, the defect of \eqref{eq:pasting-3} at a fixed question is the second-marginal defect of \eqref{eq:pasting-1} plus a term bounded by the pinched defect $\Delta_1 = \sum_{a_1,g_2} \langle \psi | A_{a_1} \ot G_{g_2} (\Id - P_{a_1}) G_{g_2} | \psi \rangle$, and by Cauchy--Schwarz $\Delta_1$ is at most the first-marginal defect plus the square root of the commutator sum $K = \sum_{a_1,g_2} \| \Id \ot [P_{a_1}, G_{g_2}] \, \psi \|^2$. The coarse commutators $[P_{a_1}, Q_{a_2}]$ are small on the second factor because both marginal families are consistent, by \eqref{eq:pasting-1}, with the marginals of the joint projective measurement $A$ on the first factor. Expanding $K$ and its coarse counterpart into four terms each and comparing term by term, the first difference is controlled by the near-projectivity of $P$ on the state, the second vanishes by projectivity of $(G_2)^x$, and in the two cross terms the rightmost effect is moved to the first factor. That move is where \eqref{eq:pasting-1-sym} enters: together with \eqref{eq:pasting-2} and the second comparison in \eqref{eq:pasting-1} it gives $Q_{a_2} \ot \Id \simeq_{\delta + 2\sqrt{2\delta}} \Id \ot Q_{a_2}$, and the $\eta$-bound on the agreement of distinct functions in $\mathcal G_2$ upgrades this to the fine effects $G_{g_2}$. After the move, the coarse cross term exceeds the fine one by a sum, over colliding pairs $g_2 \ne g_2'$, of expectations of tensor products of positive operators, which is nonnegative and at most $\eta$ on average. The resulting bound is a universal sum of positive powers of $\delta$ and $\eta$, as required by \eqref{eq:def-deltap}.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-measurement}
	\lean{MIPStarRE.QPBT.pastedMeasurement_isMeasurement}
	\leanok
	\uses{def:povm-conventions}
	This formalization-only auxiliary is not a named statement of the paper; it
	isolates the assertion, left implicit in~\eqref{eq:pasting-2a}, that the
	pasted family is a POVM. If $\{(G_1)^x_{g_1}\}_{g_1}$ is a measurement and
	$\{(G_2)^x_{g_2}\}_{g_2}$ is a projective measurement, then every operator
	$J^x_{g_1,\,g_2}$ is positive and
	$\sum_{g_1,\,g_2} J^x_{g_1,\,g_2} = \Id$.
\end{lemma}
\begin{proof}
	\leanok \uses{lem:distance-measurement-effect-hermitian}
	Positivity holds because $J^x_{g_1,\,g_2}$ is the conjugation of the
	positive operator $(G_1)^x_{g_1}$ by the self-adjoint operator
	$(G_2)^x_{g_2}$. Summing over $g_1$ first leaves
	$\sum_{g_2} (G_2)^x_{g_2} (G_2)^x_{g_2}$, which equals
	$\sum_{g_2} (G_2)^x_{g_2} = \Id$ by idempotence and completeness.
\end{proof}

\begin{definition}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{def:pasting-tensor-placement}
	\lean{MIPStarRE.QPBT.Measurement.leftPlacement, MIPStarRE.QPBT.Measurement.rightPlacement, MIPStarRE.QPBT.Measurement.leftPlacement_effect, MIPStarRE.QPBT.Measurement.rightPlacement_effect}
	\leanok
	\uses{def:povm-conventions, def:tensor-product-strategy}
	This formalization-only definition presents a POVM placed on one factor of a
	bipartite space as a POVM on that space. For a measurement $\{M_a\}_a$ on the
	first factor the placed effects are $M_a \ot \Id$; for a measurement on the
	second factor they are $\Id \ot M_a$. In both cases the effects are positive
	and sum to the identity of the bipartite space, so the comparisons of
	Lemma~\ref{lem:pasting}, whose two sides are placed families, are comparisons
	of measurements and the consistency calculus applies to them.
\end{definition}

\begin{definition}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{def:pasting-alphabet-relabelling}
	\lean{MIPStarRE.QPBT.Measurement.congrAlphabet, MIPStarRE.QPBT.Measurement.congrAlphabet_effect, MIPStarRE.QPBT.Measurement.isProjective_congrAlphabet, MIPStarRE.QPBT.Measurement.postprocess_congrAlphabet}
	\leanok
	\uses{def:povm-conventions}
	This formalization-only definition relabels the outcome set of a POVM along
	a bijection: the effect at an outcome of the new set is the effect at its
	image. The relabelled family is a POVM, it is projective whenever the
	original one is, and postprocessing it along a map agrees with
	postprocessing the original family along the transported map. The
	comparisons of Lemma~\ref{lem:pasting} are indexed by pairs of answers,
	while the commutation estimate they feed is indexed by triples; the
	relabelling mediates between the two indexings.
\end{definition}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-tensor-placement}
	\lean{MIPStarRE.QPBT.Measurement.isProjective_leftPlacement, MIPStarRE.QPBT.Measurement.isProjective_rightPlacement, MIPStarRE.QPBT.Measurement.leftPlacement_postprocess, MIPStarRE.QPBT.Measurement.rightPlacement_postprocess}
	\leanok
	\uses{def:pasting-tensor-placement}
	This formalization-only auxiliary collects the properties of the placement
	used in Lemma~\ref{lem:pasting}. The placement of a projective measurement is
	projective, and the placement of a postprocessed measurement has the same effects as the
	postprocessing of the placed measurement.
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:distance-measurement-effect-hermitian}
	Projectivity follows from the multiplicativity of the placement together
	with the idempotence and self-adjointness of the effects. Compatibility with
	postprocessing is the additivity of the tensor placement applied to the sum
	of the effects over a fibre.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-codeword-cross-consistency}
	\lean{MIPStarRE.QPBT.consistencyDefect_codeword_cross_le}
	\leanok
	\uses{def:pasting-tensor-placement, fact:triangle-for-simeq, fact:data-processing}
	In the setting of Lemma~\ref{lem:pasting}, write
	$Q_{a_2} = (G_2)^x_{[\operatorname{eval}_{y_2}(\cdot)=a_2]}$ for the coarse
	second codeword family. Then \eqref{eq:pasting-1-sym}, \eqref{eq:pasting-2}
	and the second comparison in \eqref{eq:pasting-1} give
	\[
		Q_{a_2} \ot \Id \simeq_{\delta + 2\sqrt{2\delta}} \Id \ot Q_{a_2}\,.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{fact:triangle-for-simeq, fact:data-processing}
	Coarse-graining the self-consistency \eqref{eq:pasting-2} along the second
	answer coordinate gives the consistency of the second answer marginal with
	its copy on the opposite factor, with the same error. The triangle estimate
	applied to \eqref{eq:pasting-1-sym}, to that marginal and to the second
	comparison in \eqref{eq:pasting-1} yields the assertion.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-coarse-commutator}
	\lean{MIPStarRE.QPBT.exists_coarse_commutator_bound}
	\leanok
	\uses{def:pasting-alphabet-relabelling, lem:commutation-analysis,
		fact:agreement, def:povm-distance}
	In the setting of Lemma~\ref{lem:pasting}, write
	$P_{a_1} = (G_1)^x_{[\operatorname{eval}_{y_1}(\cdot)=a_1]}$ and
	$Q_{a_2} = (G_2)^x_{[\operatorname{eval}_{y_2}(\cdot)=a_2]}$ for the two
	coarse codeword families. There is a universal constant $C \ge 1$,
	independent of the finite sets, of the space, of the distribution, of the
	measurements, of the state and of the error, such that the two comparisons
	in \eqref{eq:pasting-1} give
	\[
		\Id \ot [P_{a_1},\, Q_{a_2}] \approx_{C \delta} 0\,.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:commutation-analysis, fact:agreement,
		def:pasting-alphabet-relabelling}
	The two comparisons bound the consistency of each coarse family with the
	corresponding marginal of the joint projective measurement $A$ placed on the
	opposite factor, hence by Lemma~\ref{fact:agreement} the state-dependent
	distances of those two pairs by $2\delta$. Relabelling the outcome sets of
	$P$, of $Q$ and of $A$ so that the two coarse families are the two marginals
	of a common joint outcome set, the right-register form of
	Lemma~\ref{lem:commutation-analysis} applies and gives the assertion with
	twice its constant.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-collision-averaging}
	\lean{MIPStarRE.QPBT.avgOver_collision_le}
	\leanok
	In the setting of Lemma~\ref{lem:pasting}, let
	$c_{x,y_1}(g_2, g_2') \ge 0$ be weights indexed by pairs of second
	codewords, with $\sum_{g_2 \ne g_2'} c_{x,y_1}(g_2, g_2') \le 1$ for every
	pair $(x, y_1)$. Then the average against $\mathcal D$ of the part of that
	total carried by the colliding pairs is at most $\eta$:
	\[
		\E_{(x,y_1,y_2) \sim \mathcal D}
			\sum_{\substack{g_2 \ne g_2' \\ g_2(y_2) = g_2'(y_2)}}
				c_{x,y_1}(g_2, g_2') \le \eta\,.
	\]
\end{lemma}
\begin{proof}
	\leanok
	Exchange the average over $y_2$ with the sum over pairs. A pair of distinct
	codewords contributes its weight times the mass of the second questions at
	which the two codewords agree, which is at most $\eta$ times the marginal
	mass of $(x, y_1)$ by the conditional collision hypothesis; a pair
	$(x, y_1)$ of zero marginal mass contributes nothing. Bounding the total
	weight of the pairs by one and summing the marginal over $(x, y_1)$ gives
	the assertion.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-fine-coarse-cross}
	\lean{MIPStarRE.QPBT.consistencyDefect_codeword_fine_le_coarse_add}
	\leanok
	\uses{lem:pasting-collision-averaging, def:pasting-tensor-placement}
	In the setting of Lemma~\ref{lem:pasting}, write $G_{g_2} = (G_2)^x_{g_2}$
	for the fine second codeword family and
	$Q_{a_2} = (G_2)^x_{[\operatorname{eval}_{y_2}(\cdot)=a_2]}$ for its
	coarse-graining, and let
	\[
		\epsilon_f = \E_{(x,y_1,y_2) \sim \mathcal D}
			\sum_{g_2 \ne g_2'} \bra{\psi} G_{g_2} \ot G_{g_2'} \ket{\psi},
		\qquad
		\epsilon_c = \E_{(x,y_1,y_2) \sim \mathcal D}
			\sum_{a_2 \ne a_2'} \bra{\psi} Q_{a_2} \ot Q_{a_2'} \ket{\psi}
	\]
	be the cross consistency defects of the two families. Then
	$\epsilon_f \le \epsilon_c + \eta$.
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:pasting-collision-averaging}
	At a fixed question both defects equal $\|\psi\|^2$ minus the corresponding
	diagonal overlap, and the diagonal overlap of the coarse family is the sum
	of the fine overlaps over the pairs of codewords agreeing at $y_2$.
